insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sem prejuízo das atribuições das Forças Armadas, dos órgãos de segurança pública e do sistema prisional, são serviços de segurança privada: vigilância patrimonial; segurança de eventos em espaços de uso comum do povo; segurança nos transportes coletivos terrestres, aquaviários e marítimos; segurança perimetral em muralhas e guaritas; segurança em unidades de conservação; monitoramento de sistemas eletrônicos de segurança e rastreamento de numerário, bens ou valores; transporte de numerário, bens ou valores; escolta desses valores; segurança pessoal; formação e atualização de profissionais; gerenciamento de riscos em operações de transporte de valores; controle de acesso em portos e aeroportos; e outros serviços definidos em regulamento. Os serviços dos incisos I, IV, V, VII, VIII, IX, X e XII podem ser prestados com armas de fogo, nas condições do regulamento.', '["Rol de serviços de segurança privada (treze incisos).","Vigilância patrimonial, transporte e escolta de valores, segurança pessoal e outros.","Alguns podem usar arma de fogo, conforme regulamento."]'::jsonb, '["Escolta e transporte de valores, vigilância e segurança pessoal podem ser armados.","Monitoramento eletrônico não é armado."]'::jsonb, 'A empresa de vigilância patrimonial pode usar vigilantes armados, nas condições do regulamento.', '["Assertiva que proíbe o uso de arma de fogo em todos os serviços de segurança privada erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-5' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6fc669f081e7d05a0170fffa640b2d93a9a6462af56d31b76dad229194813cc8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O transporte de numerário, bens ou valores, quando envolver suprimento ou recolhimento de numerário das instituições financeiras, será realizado com veículos especiais blindados, com no mínimo 4 vigilantes especialmente habilitados, sendo 1 vigilante-motorista. Na escolta poderão ser usados veículos blindados, nas hipóteses do regulamento. As empresas de transporte poderão transportar chave de cofre, documento, malote e outros bens; realizar o suprimento e o recolhimento de numerário e acompanhar o atendimento técnico de caixas eletrônicos, vedadas a preparação e a contagem no local; e armazenar, custodiar e processar o numerário. É vedada a locomoção dos veículos entre as 20h e as 8h, salvo casos do regulamento. Os veículos de transporte e de escolta armada são considerados prestadores de serviços de utilidade pública.', '["Veículo blindado com no mínimo 4 vigilantes, um deles motorista.","Serviços correlatos permitidos às empresas de transporte.","Vedada a locomoção entre as 20h e as 8h, salvo regulamento.","Veículos de utilidade pública."]'::jsonb, '["Mínimo de 4 vigilantes (1 vigilante-motorista).","Proibição de circular entre as 20h e as 8h."]'::jsonb, 'O carro-forte que abastece caixas eletrônicos leva no mínimo quatro vigilantes.', '["Assertiva que permite o transporte de valores à noite, sem exceção, erra: é vedada a locomoção entre as 20h e as 8h, salvo casos de regulamento."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-6' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9089921e1886b4775461740406edfa428f6e320ae07242c61bc0bfdf8892a5d9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O serviço de monitoramento de sistemas eletrônicos de segurança compreende a elaboração de projeto que integre equipamentos eletrônicos de segurança privada; a locação, comercialização, instalação e manutenção desses equipamentos; e a assistência técnica e a inspeção técnica. A inspeção técnica consiste no deslocamento de profissional desarmado ao local de origem do sinal enviado pelo sistema eletrônico para verificação, registro e comunicação do evento à central de monitoramento.', '["Projeto, locação, comercialização, instalação e manutenção de equipamentos.","Assistência e inspeção técnica.","Inspeção por profissional DESARMADO."]'::jsonb, '["A inspeção técnica é feita por profissional DESARMADO."]'::jsonb, 'O técnico desarmado vai ao local do alarme para verificar e comunicar o evento à central.', '["Assertiva que permite a inspeção técnica armada erra: o profissional é desarmado."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-7' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '973b023e2be51eae791f813e4143f7e48cddb20e9b3a80778f9039bcb7523448'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A empresa de segurança privada contratada para eventos que, por sua magnitude e complexidade, mereçam planejamento específico, definidos em regulamento, deverá apresentar previamente projeto de segurança à autoridade local competente. O projeto conterá, entre outras exigências, o público estimado, a descrição da quantidade e da disposição dos vigilantes e a análise de risco, considerando o tipo de evento e o público-alvo, a localização, os pontos de entrada, saída e circulação do público e os dispositivos de segurança existentes.', '["Projeto de segurança prévio em eventos de grande complexidade.","Conteúdo: público estimado, vigilantes e análise de risco.","Apresentação à autoridade local competente."]'::jsonb, '["Projeto PRÉVIO à autoridade local."]'::jsonb, 'A empresa apresenta o projeto de segurança de um grande show antes do evento.', '["Assertiva que dispensa o projeto de segurança em eventos complexos erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-8' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd01a40e8bcfb51f7904443d154ebd8d701c9c525e660706fb0583e29c260c294'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos eventos realizados em estádios, ginásios e locais similares, poderá ser utilizado o serviço de segurança privada, em complemento e com integração à atividade dos órgãos de segurança pública.', '["Segurança privada em estádios e ginásios.","Em complemento e integração com a segurança pública."]'::jsonb, '["Complementar, e não substitui a segurança pública."]'::jsonb, 'Vigilantes privados trabalham no estádio junto com a Polícia Militar.', '["Assertiva que substitui a segurança pública pela privada nos estádios erra: é complementar."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-9' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '998f5e819923538e5c22d5a612f7be6713fb9b99340b56f04968740a951f8b0e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
