insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As empresas de segurança privada poderão prestar serviços ligados à atividade de bombeiro civil, desenvolvida por profissionais capacitados, nos termos da Lei nº 11.901, de 12 de janeiro de 2009, vedado o exercício simultâneo das funções de vigilância e de prevenção e combate a incêndios pelo mesmo profissional. O integrante de Corpo de Bombeiros Militar, na inatividade, será considerado habilitado a exercer a atividade de bombeiro civil, respeitados os requisitos da Lei nº 11.901.', '["Serviços de bombeiro civil por profissionais capacitados.","Vedada a função simultânea de vigilante e bombeiro.","Bombeiro militar inativo é considerado habilitado."]'::jsonb, '["Vedado acumular vigilância e combate a incêndio no mesmo profissional."]'::jsonb, 'A empresa oferece brigadistas e vigilantes, mas em profissionais diferentes.', '["Assertiva que permite o mesmo profissional exercer vigilância e combate a incêndio simultaneamente erra."]'::jsonb, '[]'::jsonb, '["Lei do Bombeiro Civil"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-10' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e13f1910c9fe249128a3dcaa93080028397099bc1a8dd040b08a7ff450192d03'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
