insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedada a utilização de produtos controlados de uso restrito na prestação de serviços de segurança privada, salvo nos casos definidos em regulamento.', '["Vedados produtos controlados de uso restrito.","Exceções definidas em regulamento."]'::jsonb, '["Regra: só uso PERMITIDO."]'::jsonb, 'A empresa de vigilância não usa fuzil de uso restrito, salvo exceção regulamentar.', '["Assertiva que autoriza o uso livre de armas de uso restrito na segurança privada erra."]'::jsonb, '[]'::jsonb, '["Estatuto do Desarmamento"]'::jsonb, 'under_review', 'claude'
