insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os efeitos da Lei, consideram-se prestadores de serviço de segurança privada as pessoas jurídicas autorizadas a prestar os serviços previstos no art. 5º.', '["Prestadores são pessoas jurídicas autorizadas."]'::jsonb, '["Prestador é sempre pessoa JURÍDICA autorizada."]'::jsonb, 'A empresa autorizada pela PF é prestadora de segurança privada.', '["Assertiva que considera prestador uma pessoa física não autorizada erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-12' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7183feb5ae79510986f8828c5d97cbb8ea011e42c73be8b609f0df578ba4cf94'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São prestadores de serviço de segurança privada as empresas de serviço de segurança privada (serviços dos incisos I a V, VII a IX, XI e XII do art. 5º), as escolas de formação de profissional de segurança privada (inciso X) e as empresas de monitoramento de sistema eletrônico de segurança (inciso VI). As empresas de serviço de segurança podem usar sistemas eletrônicos de segurança. As escolas e as empresas de monitoramento não podem oferecer os serviços de vigilância. A Polícia Federal classifica as empresas que prestarem exclusivamente os serviços do inciso XIII. Podem ser utilizados animais na execução das atividades, conforme regulamento.', '["Três tipos: empresas de segurança, escolas de formação e empresas de monitoramento.","Escolas e empresas de monitoramento não oferecem vigilância.","Uso de animais conforme regulamento."]'::jsonb, '["Escola de formação e empresa de monitoramento NÃO podem fazer vigilância."]'::jsonb, 'A empresa de monitoramento não pode oferecer vigilantes patrimoniais.', '["Assertiva que permite à escola de formação oferecer vigilância patrimonial erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-13' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7b07c0b2b6a67c9867327c817fcdfb917137024c04800af7d49a0cee4e937606'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
