insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O capital social mínimo integralizado para a autorização é de R$ 2.920.000,00 para empresas de transporte de numerário, bens ou valores; R$ 292.000,00 para gerenciamento de risco em operações de transporte de valores; R$ 730.000,00 para as demais empresas de serviço de segurança; R$ 292.000,00 para escolas de formação; e R$ 146.000,00 para empresas de monitoramento eletrônico. Na prestação simultânea de dois ou mais serviços somam-se R$ 146.000,00 por serviço adicional. O valor de R$ 730.000,00 será reduzido a 1/4 para empresas que prestem exclusivamente segurança patrimonial e de eventos sem arma de fogo.', '["Transporte de valores: R$ 2.920.000,00.","Demais empresas de segurança: R$ 730.000,00.","Escolas e gerenciamento de risco: R$ 292.000,00.","Monitoramento: R$ 146.000,00.","Redução a 1/4 para segurança patrimonial e de eventos sem arma."]'::jsonb, '["Capital mínimo varia conforme o tipo de empresa."]'::jsonb, 'A empresa de transporte de valores precisa de capital social de R$ 2.920.000,00.', '["Assertiva que fixa o mesmo capital mínimo para todas as empresas erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-14' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd3fe61ee0629ea97010a97ec60df1833f3b8b20abec203162f22e370d0f18780'
