insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a prestação de serviços de segurança privada, os prestadores referidos no art. 13 empregarão profissionais habilitados nos termos previstos nos incisos I a VI do caput do art. 26.', '["Só profissionais habilitados."]'::jsonb, '["Profissionais habilitados conforme o art. 26."]'::jsonb, 'A empresa só emprega vigilantes com habilitação.', '["Assertiva que permite empregar pessoal sem habilitação erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
