insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas empregadas na prestação de serviços de segurança privada serão de propriedade dos prestadores de serviço e deverão ter cadastro obrigatório no Sinarm e registro e controle pela Polícia Federal. Se as armas e produtos controlados de uso permitido tiverem sido adquiridos de outro prestador, a Polícia Federal poderá autorizar, durante o pedido de transferência de registro, o uso até a expedição do novo registro.', '["Armas pertencem aos prestadores.","Cadastro no Sinarm e registro pela Polícia Federal.","Uso provisório durante a transferência de registro."]'::jsonb, '["A arma é da EMPRESA, e não do vigilante."]'::jsonb, 'A empresa que compra armas de outra usa-as provisoriamente enquanto a PF transfere o registro.', '["Assertiva que atribui a propriedade da arma ao vigilante erra: é do prestador."]'::jsonb, '[{"termo":"Sinarm","significado":"Sistema Nacional de Armas."}]'::jsonb, '["Estatuto do Desarmamento, art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-17' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '801ea3582789cd019d92d81a5429a84d870bb53a6d02fb572816882ef1730236'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Polícia Federal deverá instituir sistema informatizado para o cadastramento dos prestadores de serviço de segurança privada, das empresas e condomínios com serviços orgânicos, dos sistemas de segurança das instituições financeiras e dos profissionais. Regulamento disporá sobre o compartilhamento de dados entre os órgãos de segurança pública, observado o sigilo legal, e sobre a divulgação de informações para controle social.', '["Sistema informatizado de cadastro da Polícia Federal.","Compartilhamento de dados entre órgãos de segurança.","Divulgação para controle social."]'::jsonb, '["Cadastro unificado pela Polícia Federal."]'::jsonb, 'A PF mantém um sistema com o cadastro das empresas e dos vigilantes.', '["Assertiva que atribui o cadastro às Secretarias de Segurança Estaduais erra: é da Polícia Federal."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-18' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f292ae3614942a4d668caf465ee343ee69ce6226d2627a5824eac7a6113cef73'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
