insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autorização de funcionamento e sua renovação dependem de: comprovação de que os sócios não tiveram cotas em empresas de segurança privada canceladas nos últimos 5 anos, nos termos do art. 46, III; nos processos de renovação, pagamento das multas aplicadas; certidões de regularidade fiscal, trabalhista, tributária e previdenciária da empresa e dos sócios; comprovação da origem lícita do capital, quando houver indícios; certidões negativas de antecedentes criminais por crime doloso dos sócios, administradores, diretores, gerentes e procuradores, nos locais em que residiram nos últimos 5 anos; e capital social mínimo integralizado.', '["Sócios sem empresa cancelada nos últimos 5 anos.","Multas pagas na renovação.","Certidões de regularidade fiscal, trabalhista, tributária e previdenciária.","Origem lícita do capital.","Certidões de antecedentes criminais por crime doloso nos últimos 5 anos de residência.","Capital social mínimo."]'::jsonb, '["Antecedentes criminais por crime DOLOSO."]'::jsonb, 'Sócio com empresa de vigilância cancelada há três anos impede a nova autorização.', '["Assertiva que dispensa as certidões de antecedentes dos administradores erra."]'::jsonb, '[]'::jsonb, '["Art. 14","Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4f1d1aafb8ef8fdf729a8c0862e49f8c6047895a8eab893004c928982178ad88'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
