insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Empresa de serviços de segurança é a pessoa jurídica, obrigatoriamente constituída na forma de sociedade limitada ou anônima de capital fechado ou aberto com ações não negociáveis em bolsa, para prestar os serviços dos incisos I a V, VII a IX, XI a XIII do art. 5º e os correlatos definidos em regulamento. A autorização depende de requisitos específicos de cada serviço, observados tipos de serviço, adequação das instalações físicas (uso exclusivo, local seguro para armas e munições, alarme, circuito de imagens e vigilância ininterrupta), veículos, quantidade e qualificação dos profissionais, armas e munições, e sistema de segurança das bases operacionais de transporte de valores.', '["Sociedade limitada ou anônima com ações não negociáveis em bolsa.","Instalações: uso exclusivo, guarda segura de armas, alarme, imagens e vigilância ininterrupta.","Requisitos por tipo de serviço."]'::jsonb, '["Forma societária restrita: limitada ou anônima sem ações em bolsa."]'::jsonb, 'A empresa de vigilância precisa de local seguro para guardar armas e munições.', '["Assertiva que permite empresa individual de segurança privada erra: exige sociedade limitada ou anônima."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-20' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '75ababd35a24409893e01bf6c2b942957ec598337befadd6b208e00343b4d7d7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a execução de suas atividades, a empresa de serviços de segurança poderá utilizar diferentes tecnologias, observados os limites legais.', '["Uso de tecnologias, dentro dos limites legais."]'::jsonb, '["Tecnologia permitida, mas limitada pela lei."]'::jsonb, 'A empresa usa câmeras e drones dentro dos limites legais.', '["Assertiva que veda o uso de tecnologia pela empresa de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-21' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ddf67f20cb345782bf29f97ec6e66ab6a5e5edf6a4cbd1ecca8f5ef683e32d9d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
