insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Escola de formação de profissional de segurança privada é a pessoa jurídica constituída para prestar os serviços de formação, aperfeiçoamento e atualização dos profissionais previstos no inciso X do art. 5º.', '["Escola de formação presta os serviços do inciso X do art. 5º."]'::jsonb, '["Escola ensina; não faz vigilância."]'::jsonb, 'A escola forma vigilantes, mas não os presta a terceiros.', '["Assertiva que permite à escola prestar vigilância erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-22' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e8757f705efe75e4b8cb44d65e4d0585a61f063f0b60dab89156ea855a7231cf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
