insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caráter excepcional, a escola de formação poderá realizar atividade de ensino distinta das do inciso X do art. 5º, desde que destinada ao aprimoramento da segurança privada e autorizada pela Polícia Federal. Poderá ceder suas instalações para aplicação de testes em atendimento às necessidades do Sinarm, com vistas ao credenciamento de instrutores de tiro ou à comprovação técnica para aquisição e manuseio de armas de fogo.', '["Ensino excepcional, autorizado pela Polícia Federal.","Cessão de instalações para testes do Sinarm."]'::jsonb, '["Exige autorização da Polícia Federal."]'::jsonb, 'A escola cede o estande para o teste de tiro do Sinarm.', '["Assertiva que dispensa autorização da PF para ensino diverso erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
