insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Empresa de monitoramento de sistemas eletrônicos de segurança privada é a constituída para prestar os serviços do inciso VI do art. 5º, exceto a comercialização isolada de produtos desses serviços. Poderá realizar monitoramento remoto de quaisquer estabelecimentos, especialmente dos locais dos incisos II, III, IV e V do art. 5º, sem prejuízo da atuação das empresas de serviço de segurança.', '["Empresa de monitoramento presta o serviço do inciso VI.","Monitoramento remoto de qualquer estabelecimento."]'::jsonb, '["Não inclui a mera comercialização isolada de produtos."]'::jsonb, 'A central monitora remotamente um shopping, sem vigilantes no local.', '["Assertiva que restringe o monitoramento remoto a bancos erra: vale para quaisquer estabelecimentos."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-24' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0e5d6f944d6cf06b17b3c6dbf15eeadcfc3d72cab9cef33961cf41817e208272'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serviços orgânicos de segurança privada são aqueles organizados facultativamente por pessoa jurídica ou condomínio edilício, para quaisquer dos serviços do art. 5º, no que couber, exceto formação (inciso X), desde que em proveito próprio, para a segurança de seu patrimônio e de seu pessoal. São instituídos com pessoal próprio, vedada a prestação a terceiros. Aplicam-se os arts. 15, 16, 17 e os incisos I a VI do art. 19. Podem usar armas de fogo e de menor potencial ofensivo de sua propriedade e a tecnologia disponível. As empresas cujo objeto social não seja segurança devem atender a requisitos do art. 20. O artigo não se refere ao controle de acesso de pessoas e veículos nas entradas dos estabelecimentos.', '["Facultativo e em proveito próprio.","Pessoal próprio, vedada a prestação a terceiros.","Aplicam-se regras de autorização e habilitação.","Armas de propriedade do prestador orgânico."]'::jsonb, '["Serviço orgânico NÃO presta segurança a terceiros."]'::jsonb, 'O condomínio mantém vigilantes próprios, contratados por ele, para seu patrimônio.', '["Assertiva que permite ao serviço orgânico prestar segurança a outras empresas erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-25' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '44c196f1a98a3468560b4925f7d769387524f99a41673a45628b3f76a2345bc8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Consideram-se profissionais de segurança privada o gestor de segurança privada, profissional de nível superior responsável pela análise de riscos, projetos de proteção, auditorias e gerenciamento de riscos em transporte de valores; o vigilante supervisor, encarregado do controle operacional; o vigilante, responsável pela execução dos serviços e pela segurança física de pessoas e do patrimônio, observando, inspecionando e fiscalizando as dependências e gerenciando o público; o supervisor de monitoramento de sistema eletrônico de segurança; o técnico externo de sistema eletrônico de segurança; e o operador de monitoramento.', '["Gestor de segurança privada (nível superior).","Vigilante supervisor.","Vigilante.","Supervisor de monitoramento.","Técnico externo.","Operador de monitoramento."]'::jsonb, '["Gestor: NÍVEL SUPERIOR."]'::jsonb, 'O vigilante controla o fluxo de pessoas e fiscaliza as dependências.', '["Assertiva que não exige nível superior do gestor de segurança privada erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-26' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1d55c85cbf99060c3c521be4afcd599f725966a407b2002454ecbdcfc2fa9b63'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
