insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O documento de identificação de gestor de segurança, vigilante supervisor e vigilante, de padrão único, será de uso obrigatório quando em serviço.', '["Documento de identificação de padrão único.","Uso obrigatório em serviço."]'::jsonb, '["Padrão ÚNICO nacional."]'::jsonb, 'O vigilante porta o documento padronizado durante o plantão.', '["Assertiva que dispensa o documento de identificação do vigilante em serviço erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-27' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9333b437c0bf4f5bb95091d31a751913bad5001e1704c9e01cbdddd6ba74ba1a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
