insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São requisitos para o exercício da atividade de vigilante e de vigilante supervisor: ser brasileiro, nato ou naturalizado; ter idade mínima de 21 anos; ter sido considerado apto em exame de saúde física, mental e psicológica; ter concluído com aproveitamento o curso de formação específico; não possuir antecedentes criminais por crimes dolosos, nem estar cumprindo pena, enquanto não obtida a reabilitação; e estar quite com as obrigações eleitorais e militares. Para vigilante exige-se ainda o ensino fundamental completo e a contratação por empresa de segurança ou serviço orgânico. Para vigilante supervisor, o ensino médio. Para supervisor de monitoramento, técnico externo e operador, idade mínima de 18 anos.', '["Brasileiro, nato ou naturalizado.","Idade mínima de 21 anos.","Aptidão física, mental e psicológica.","Curso de formação.","Sem antecedentes por crime doloso.","Quite com obrigações eleitorais e militares.","Vigilante: ensino fundamental; supervisor: ensino médio.","Operador de monitoramento e técnico externo: 18 anos."]'::jsonb, '["Vigilante: 21 anos; monitoramento e técnico externo: 18 anos."]'::jsonb, 'Um jovem de vinte anos ainda não pode ser vigilante.', '["Assertiva que permite vigilante com 18 anos erra: a idade mínima é de 21 anos."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-28' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '693d877009d63beb2d452944190801e79ba36f8144fa869f38215b8f1648ab63'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São direitos do vigilante supervisor e do vigilante: atualização profissional; uniforme especial autorizado pela Polícia Federal; porte de arma de fogo quando em efetivo serviço; materiais e equipamentos de proteção individual em perfeito estado; seguro de vida em grupo; assistência jurídica por ato decorrente do serviço; serviço autônomo de aprendizagem e assistência social; e piso salarial fixado em acordos e convenções coletivas. Os direitos serão providenciados a expensas do empregador. O armamento, a munição e os coletes terão especificações definidas pela Polícia Federal. Ao técnico externo, ao operador e ao supervisor de monitoramento assegura-se parte desses direitos. Convenção ou acordo coletivo pode ajustar jornada de 12 horas por 36 horas de descanso.', '["Rol de direitos a expensas do empregador.","Porte de arma só em efetivo serviço.","Seguro de vida e assistência jurídica.","Piso salarial por convenção coletiva.","Jornada 12x36 por convenção ou acordo coletivo."]'::jsonb, '["Porte de arma apenas EM EFETIVO SERVIÇO.","Jornada 12 por 36 só por convenção ou acordo coletivo."]'::jsonb, 'O vigilante só porta arma durante o expediente.', '["Assertiva que garante porte de arma ao vigilante fora do serviço erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-29' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'af7a9d2ed4768b187086b69562e4a5873e9570263bd180dbcf5eeb6c1fe3e69e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São deveres dos profissionais de segurança privada: respeitar a dignidade e a diversidade da pessoa humana; exercer as atividades com probidade, desenvoltura e urbanidade; comunicar ao chefe imediato incidentes e irregularidades no equipamento; usar corretamente o uniforme e portar identificação; manter-se adstrito ao local sob vigilância; e manter o sigilo profissional, ressalvado o compromisso com a denúncia de ação delituosa. Devem prestar serviços uniformizados, salvo hipóteses do regulamento. Os deveres não eximem o empregador de fiscalizar seu cumprimento.', '["Respeito à dignidade e à diversidade.","Probidade e urbanidade.","Comunicação de incidentes.","Uso do uniforme e identificação.","Permanência no local vigiado.","Sigilo, ressalvada a denúncia de crime."]'::jsonb, '["Sigilo cede diante da denúncia de ação delituosa."]'::jsonb, 'O vigilante comunica ao chefe um defeito no equipamento de rádio.', '["Assertiva que impede a denúncia de crime em razão do sigilo profissional erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-30' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '55e9a5127c2c29327b3daf0c96869b6264e324980a9e7384e1563c2fe0cfd162'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O funcionamento de dependências de instituições financeiras onde haja, simultaneamente, atendimento ao público e guarda ou movimentação de numerário ou valores fica condicionado à aprovação do plano de segurança pela Polícia Federal. Os estabelecimentos incluem bancos oficiais ou privados, caixas econômicas, sociedades de crédito, associações de poupança, agências e postos, cooperativas singulares de crédito e respectivas dependências. A Lei não se aplica a agências e postos de cooperativas singulares localizados em Municípios com população inferior a 20.000 habitantes, cujos requisitos serão definidos em regulamento.', '["Plano de segurança aprovado pela Polícia Federal.","Abrange bancos, caixas, cooperativas e outras instituições.","Exceção para cooperativas em Municípios com menos de 20.000 habitantes."]'::jsonb, '["Exceção: cooperativas singulares em cidades com menos de 20.000 habitantes."]'::jsonb, 'A agência só abre após a Polícia Federal aprovar o plano de segurança.', '["Assertiva que dispensa o plano de segurança das agências bancárias erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-31' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '371c9870a34ddacee16246cc802883aa363336987b81b7f7034d382e180d432d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se à segurança das instituições financeiras e ao transporte de numerário ou valores a elas destinados os procedimentos específicos estabelecidos pela Polícia Federal, nos limites do disposto na Lei e em sua regulamentação.', '["Procedimentos específicos da Polícia Federal."]'::jsonb, '["Competência regulamentar da Polícia Federal."]'::jsonb, 'A PF fixa procedimentos específicos para o carro-forte.', '["Assertiva que atribui ao Banco Central os procedimentos de segurança das agências erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-32' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '36d435c79a06777f9758071bb2a255ba248aa71cc05100301a01c9b75ad66692'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adequação dos itens de segurança nas dependências de instituições financeiras será fiscalizada pela Polícia Federal. Nas agências bancárias, o sistema de segurança deverá contar com instalações físicas adequadas; no mínimo 2 vigilantes armados ou com arma de menor potencial ofensivo e coletes balísticos durante o atendimento; alarme interligado; cofre com dispositivo temporizador; circuito de imagens com armazenamento em tempo real por no mínimo 60 dias; artefatos que garantam a privacidade nos guichês dos caixas, nas capitais e cidades com mais de 500.000 habitantes; e procedimento de segurança para a abertura do estabelecimento e dos cofres. Os postos de atendimento bancário com atendimento e guarda ou movimentação de valores deverão ter no mínimo 1 vigilante e circuito de imagens.', '["Mínimo de 2 vigilantes nas agências, durante o atendimento.","Imagens armazenadas por no mínimo 60 dias.","Cofre com temporizador e alarme interligado.","Privacidade nos guichês em capitais e cidades com mais de 500.000 habitantes.","Postos de atendimento: mínimo de 1 vigilante."]'::jsonb, '["Agência: 2 vigilantes; posto de atendimento: 1 vigilante.","Imagens guardadas por no mínimo 60 dias."]'::jsonb, 'A agência mantém ao menos dois vigilantes durante o atendimento ao público.', '["Assertiva que exige apenas um vigilante nas agências bancárias erra: são no mínimo dois."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-33' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a69cafba61ff6a43e5d9698d58bce04cbb0f8272f1c5496579e19a5477e213fa'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O plano de segurança deverá descrever todos os elementos do sistema de segurança, abranger toda a área do estabelecimento e conter: descrição da quantidade e disposição dos vigilantes; descrição da localização e das instalações; planta baixa com os pontos de acesso, os locais de guarda de numerário, valores e armas e a localização dos vigilantes e dispositivos; comprovante de autorização de serviço orgânico ou de contrato com prestador de segurança; e projetos de construção, instalação e manutenção de sistemas eletrônicos. A Polícia Federal poderá disciplinar informações adicionais. O acesso ao plano é restrito ao órgão de fiscalização e às pessoas autorizadas pela instituição.', '["Conteúdo do plano de segurança.","Planta baixa e comprovante de autorização ou contrato.","Acesso restrito ao plano."]'::jsonb, '["O plano é de acesso RESTRITO."]'::jsonb, 'O banco entrega à PF a planta baixa com os pontos de segurança.', '["Assertiva que torna público o plano de segurança erra: o acesso é restrito."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-34' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6817ba4bebbdf22562da74f39504a5be70ebbd0780e48635fd84572143c70192'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A edição de normas relativas à segurança das instituições financeiras deverá ser precedida de análise técnica que, a critério da Polícia Federal, resulte na sua efetividade.', '["Análise técnica prévia das normas de segurança bancária."]'::jsonb, '["Análise técnica antes de editar normas."]'::jsonb, 'A PF faz análise técnica antes de editar nova norma de segurança bancária.', '["Assertiva que dispensa a análise técnica prévia das normas erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
