and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O transporte, a guarda e o manuseio de numerário ou valores, inclusive o intermodal, para suprimento e coleta de instituições financeiras, serão feitos por empresas de serviços de segurança autorizadas ao transporte de valores ou por serviço orgânico de segurança. Onde for comprovada a impossibilidade ou inviabilidade de veículos blindados terrestres, o transporte poderá ser feito por via aérea, marítima ou fluvial ou por outros meios adequados, observadas as normas, os elementos mínimos de segurança e a presença de vigilantes especialmente habilitados.', '["Transporte por empresas autorizadas ou serviço orgânico.","Transporte aéreo, marítimo ou fluvial se inviável o blindado terrestre."]'::jsonb, '["Alternativa por via aérea, marítima ou fluvial exige comprovação à Polícia Federal."]'::jsonb, 'Em região isolada, o transporte de valores é feito por barco com vigilantes habilitados.', '["Assertiva que permite o transporte aéreo sem comprovação de inviabilidade terrestre erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
