select u.id, u.content_sha256, 'É vedada aos empregados da instituição financeira a execução de transporte de numerário ou valores.', '["Empregados do banco não transportam valores."]'::jsonb, '["Vedação dirigida aos empregados da instituição financeira."]'::jsonb, 'O funcionário do banco não leva o dinheiro entre agências.', '["Assertiva que permite ao bancário transportar valores erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
