insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É permitida a guarda de chaves de cofres e das dependências de instituições financeiras nas instalações de empresas de serviços de segurança.', '["Guarda de chaves de cofres nas empresas de segurança."]'::jsonb, '["Faculdade permitida."]'::jsonb, 'A empresa de segurança guarda as chaves do cofre da agência.', '["Assertiva que proíbe a guarda de chaves de cofres por empresas de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
