insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O uso de tecnologias de inutilização do numerário e de outros dispositivos antifurtos empregados nos sistemas de segurança será disciplinado pela Polícia Federal, ouvido, sempre que necessário, o Banco Central do Brasil.', '["Tecnologias de inutilização de cédulas disciplinadas pela Polícia Federal.","Banco Central ouvido quando necessário."]'::jsonb, '["Regulação pela PF, com oitiva do Banco Central."]'::jsonb, 'A PF regula o uso de tinta que inutiliza as cédulas.', '["Assertiva que atribui ao Banco Central, exclusivamente, essa regulação erra: é da PF, ouvido o Banco Central."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
