insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No âmbito da segurança privada, compete à Polícia Federal: conceder autorização de funcionamento aos prestadores e aos serviços orgânicos; renová-la a cada 2 anos para as empresas de serviços de segurança, escolas de formação e serviços orgânicos, e a cada 5 anos para as empresas de monitoramento; controlar e fiscalizar os prestadores, serviços orgânicos e sistemas de segurança das instituições financeiras, apurar responsabilidades e aplicar sanções; estabelecer procedimentos específicos; reprimir atividades ilegais ou clandestinas, sem prejuízo do auxílio das polícias estaduais; estabelecer condições para sistemas de comunicação e eletrônicos; e autorizar a aquisição, utilização, custódia, alienação e destruição de armas, munições e equipamentos.', '["Autorização e renovação de funcionamento.","Renovação a cada 2 anos (segurança, escolas, orgânicos) e a cada 5 anos (monitoramento).","Controle, fiscalização e sanções.","Repressão à atividade clandestina.","Autorização de armas e equipamentos."]'::jsonb, '["Renovação: 2 anos (empresas de segurança, escolas e orgânicos) e 5 anos (monitoramento)."]'::jsonb, 'A empresa de vigilância renova a autorização a cada dois anos.', '["Assertiva que fixa em 5 anos a renovação das empresas de vigilância erra: são 2 anos."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-40' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a520d8c1596ce5929074997173cfe6bab2f05e6517655d80dff6d50e5e5fe435'
