insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As empresas de serviços de segurança privada e as escolas de formação deverão informar à Polícia Federal, na periodicidade do regulamento, a relação de empregados, armas e produtos controlados, veículos e contratos, entre outras informações. As empresas e condomínios com serviços orgânicos informarão relação dos empregados, armas, veículos e produtos controlados. As empresas de transporte de valores manterão registro diário de todas as operações, com a identificação dos contratantes, para fornecimento às autoridades.', '["Informações periódicas à Polícia Federal.","Orgânicos também informam.","Transporte de valores: registro diário de operações."]'::jsonb, '["Registro DIÁRIO nas empresas de transporte de valores."]'::jsonb, 'A transportadora de valores registra diariamente suas operações e contratantes.', '["Assertiva que dispensa o registro diário das operações de transporte de valores erra."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
