insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os contratantes de prestadores de serviço de segurança privada informarão à Polícia Federal, quando por ela requeridos, os dados não financeiros referentes aos respectivos contratos.', '["Contratantes informam dados não financeiros dos contratos, quando requeridos."]'::jsonb, '["Apenas dados NÃO FINANCEIROS."]'::jsonb, 'O condomínio informa à PF dados do contrato de vigilância, sem valores.', '["Assertiva que obriga a informar os valores financeiros do contrato erra: são dados não financeiros."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
