insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Polícia Federal aplicar penalidades administrativas por infração aos dispositivos da Lei. Aplica-se subsidiariamente aos processos punitivos a Lei do Processo Administrativo Federal (Lei nº 9.784, de 29 de janeiro de 1999).', '["Penalidades aplicadas pela Polícia Federal.","Aplicação subsidiária da Lei do Processo Administrativo Federal."]'::jsonb, '["Lei do processo administrativo federal é subsidiária."]'::jsonb, 'A PF aplica multa à empresa que descumpre a lei.', '["Assertiva que atribui a aplicação das penalidades à Justiça erra: é da Polícia Federal."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-45' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b1b9ce54411b6ad0abc5047f0ba05f7a5ce0fcde596ed164b8d1b7faa8d5cfea'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
