insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penalidades administrativas aplicáveis aos prestadores e aos serviços orgânicos, conforme a conduta, a gravidade, as consequências e a reincidência, são advertência; multa de R$ 1.000,00 a R$ 15.000,00; e cancelamento da autorização. A multa pode ser aumentada até o triplo se ineficaz em razão da situação econômica do infrator ou se a conduta envolver preconceito de origem, raça, sexo, cor, idade ou outra discriminação. Podem ser impostas as penas a quem contratar serviços de segurança privada em desconformidade com a Lei.', '["Advertência, multa e cancelamento da autorização.","Multa de R$ 1.000,00 a R$ 15.000,00.","Aumento até o triplo em caso de ineficácia ou discriminação.","Também ao contratante irregular."]'::jsonb, '["Multa de R$ 1.000,00 a R$ 15.000,00, podendo triplicar."]'::jsonb, 'A empresa que discrimina um candidato recebe multa até o triplo.', '["Assertiva que fixa o teto da multa em R$ 50.000,00 sem aumento erra: o teto é R$ 15.000,00, podendo triplicar."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-46' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ec32981f847a00617f55d61a0c7be6fe9af093672606eb2ef8d75996f0e7c8ab'
