insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penalidades aplicáveis às instituições financeiras são advertência; multa de R$ 10.000,00 a R$ 30.000,00 para instituições financeiras e de R$ 1.000,00 a R$ 10.000,00 para cooperativas singulares de crédito; e interdição do estabelecimento. A multa pode ser aumentada até o triplo se envolver discriminação. A reincidência caracteriza-se de forma individualizada para cada dependência. É vedado o funcionamento sem plano de segurança aprovado, sujeitando-se à interdição após processo com contraditório e ampla defesa. Obtida a aprovação antes do julgamento, a interdição converte-se em multa. É vedada a interdição cautelar.', '["Advertência, multa e interdição.","Multas: R$ 10.000,00 a R$ 30.000,00 (instituições) e R$ 1.000,00 a R$ 10.000,00 (cooperativas).","Reincidência individualizada por dependência.","Funcionamento sem plano aprovado leva à interdição.","Vedada a interdição cautelar."]'::jsonb, '["Interdição NÃO pode ser aplicada de forma cautelar.","Reincidência é contada por dependência."]'::jsonb, 'A agência sem plano de segurança aprovado pode ser interditada ao final do processo.', '["Assertiva que permite a interdição cautelar da agência erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
