insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Polícia Federal aplicará a multa do inciso II do art. 47 às pessoas físicas ou jurídicas de direito público ou privado que organizarem, oferecerem ou contratarem serviço de segurança privada sem observar a Lei, sem prejuízo da cessação imediata do serviço e das sanções civis, penais e administrativas. A multa poderá ser aumentada até o triplo se ineficaz. Constatado serviço não autorizado, a PF determinará de imediato o encerramento da segurança no local. Os materiais utilizados serão apreendidos e, ao fim do procedimento, destruídos, ressalvada a destinação prevista em lei específica.', '["Multa a quem organizar, oferecer ou contratar serviço irregular.","Encerramento imediato do serviço não autorizado.","Apreensão e destruição dos materiais."]'::jsonb, '["Encerramento IMEDIATO do serviço clandestino."]'::jsonb, 'A PF encerra no local a segurança prestada por empresa não autorizada.', '["Assertiva que isenta o contratante do serviço clandestino de penalidade erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-48' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'faf799f54056dd89e20e085ce457d0bcceff3886561a4678eacd34d5085ded51'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Polícia Federal poderá celebrar termo de compromisso de conduta com os prestadores, as empresas e condomínios com serviços orgânicos e as instituições financeiras. O termo especificará as obrigações para cessar a prática irregular e os valores das multas pelo descumprimento. Pode ser celebrado até o julgamento do processo administrativo e constitui título executivo extrajudicial. Os processos ficam suspensos durante o cumprimento e são arquivados ao término se atendidas as condições. Descumprido, a PF aplica de imediato as sanções.', '["Termo de compromisso de conduta.","Celebrado até o julgamento do processo.","Título executivo extrajudicial.","Processo suspenso e depois arquivado se cumprido."]'::jsonb, '["Título executivo EXTRAJUDICIAL."]'::jsonb, 'A empresa assina termo para corrigir irregularidades e o processo fica suspenso.', '["Assertiva que impede o termo de compromisso após o início do processo administrativo erra: pode ser celebrado até o julgamento."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd805c468ad2ae38f897243b66767f75b954b16f7721da80314acfa1fe75ed80b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Organizar, prestar ou oferecer serviços de segurança privada, com a utilização de armas de fogo, na qualidade de sócio ou proprietário, sem possuir autorização de funcionamento: detenção de 1 a 3 anos e multa.', '["Crime de segurança privada armada sem autorização.","Detenção de 1 a 3 anos e multa."]'::jsonb, '["Pena de DETENÇÃO de 1 a 3 anos.","Crime próprio de sócio ou proprietário."]'::jsonb, 'O dono de uma empresa de vigilância armada sem autorização da PF comete o crime.', '["Assertiva que prevê reclusão para esse crime erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
