insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São instituídas taxas, nos termos do Anexo da Lei, para remuneração pela execução dos serviços de fiscalização e controle federais, aplicáveis aos prestadores, às empresas e condomínios com serviços orgânicos e às instituições financeiras. Os prazos de recolhimento serão definidos em ato da Polícia Federal.', '["Taxas de fiscalização e controle federais.","Prazos de recolhimento em ato da Polícia Federal."]'::jsonb, '["Valores no Anexo."]'::jsonb, 'A empresa paga taxa pela vistoria realizada pela PF.', '["Assertiva que fixa os prazos de recolhimento na própria lei erra: são definidos em ato da PF."]'::jsonb, '[]'::jsonb, '["Anexo"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-51' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f879aeda45fb541678d05e5861572bb5ba7f41d286e45226b8e8bc967308ecfb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
