insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O julgamento do auto de infração seguirá o rito estabelecido pela Polícia Federal, observados o contraditório e a ampla defesa, e a cobrança do crédito decorrente da aplicação da Lei seguirá o rito do Decreto nº 70.235, de 6 de março de 1972.', '["Rito do julgamento definido pela Polícia Federal.","Cobrança pelo rito do Decreto nº 70.235."]'::jsonb, '["Contraditório e ampla defesa obrigatórios."]'::jsonb, 'A empresa se defende do auto de infração antes da multa ser cobrada.', '["Assertiva que dispensa o contraditório no julgamento do auto de infração erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-52' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3d67164b8b37aa2e12cfb1a2b9d0d40866c47db884de618c2662e129f22493c1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a execução das competências da Lei, a Polícia Federal, por meio do Ministério da Justiça e Segurança Pública, poderá celebrar convênio com as secretarias de segurança pública dos Estados e do Distrito Federal, delegando parte de suas atribuições de fiscalização e controle. A União destinará às unidades da Federação conveniadas parte dos valores arrecadados com taxas e multas, vedada a subdelegação. É vedada às unidades da Federação a instituição de taxas ou multas para cumprir a Lei.', '["Convênio com as secretarias estaduais de segurança.","Delegação de parte da fiscalização.","Repasse de parte das taxas e multas.","Vedada a subdelegação e a taxa ou multa estadual."]'::jsonb, '["Estados NÃO podem criar taxas ou multas próprias."]'::jsonb, 'O Estado conveniado fiscaliza em nome da PF e recebe parte das multas.', '["Assertiva que permite aos Estados criar taxas próprias de fiscalização erra: é vedado."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4db13622cc45f3abbb455cfc62a3cafcd369eb177eb87aba9be0fb5214d4dccb'
