insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As armas, munições, petrechos e demais produtos de uso controlado cujos empregos forem autorizados para a prestação dos serviços de segurança privada, quando penhorados, arrestados ou de qualquer forma constritos judicialmente, somente poderão ser alienados e adjudicados a outros prestadores de serviço de segurança privada. A alienação e a adjudicação dependem de manifestação favorável da Polícia Federal.', '["Venda ou adjudicação só a outros prestadores.","Manifestação favorável da Polícia Federal."]'::jsonb, '["Só outro prestador pode adquirir as armas penhoradas."]'::jsonb, 'As armas penhoradas de uma empresa só podem ser vendidas a outra empresa de segurança, com anuência da PF.', '["Assertiva que permite a venda de armas penhoradas a qualquer particular erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-56' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0ca942af3489fa9a5a17f1461d1b0764ddec7c59bdd6a5c047da35880e21bf1f'
