insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma sociedade seguradora poderá emitir, em favor de estabelecimentos financeiros, apólice que inclua cobertura de riscos de roubo e furto qualificado de numerário e valores sem comprovação de cumprimento, pelo segurado, das exigências da Lei. As apólices emitidas com infringência não terão cobertura de resseguros.', '["Seguradora só emite apólice se o segurado cumprir a Lei.","Apólices irregulares não têm resseguro."]'::jsonb, '["Vincula o seguro ao cumprimento das exigências de segurança."]'::jsonb, 'A seguradora exige prova dos requisitos de segurança antes de segurar a agência.', '["Assertiva que permite apólice sem comprovação das exigências legais erra."]'::jsonb, '[]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
