insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos seguros contra roubo e furto qualificado de estabelecimentos financeiros, serão concedidos descontos sobre os prêmios aos segurados que possuírem, além dos requisitos mínimos de segurança da Lei, outros meios de proteção, na forma do regulamento.', '["Descontos nos prêmios para quem tiver proteção adicional."]'::jsonb, '["Incentivo ao reforço da segurança."]'::jsonb, 'O banco com segurança extra paga prêmio de seguro menor.', '["Assertiva que veda descontos nos seguros bancários erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
