insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No transporte dos produtos controlados referidos no decreto específico, especialmente pólvoras, explosivos e artigos pirotécnicos, em carregamentos superiores a 50 kg, é obrigatório o emprego de veículos dotados de sistema de rastreamento e de monitoramento permanentes, além de escolta armada.', '["Carga superior a 50 kg de explosivos e similares.","Rastreamento e monitoramento permanentes.","Escolta armada."]'::jsonb, '["Acima de 50 kg: rastreamento permanente E escolta armada."]'::jsonb, 'O caminhão com explosivos acima de 50 kg segue com escolta armada.', '["Assertiva que dispensa a escolta armada em carga acima de 50 kg erra."]'::jsonb, '[]'::jsonb, '["Art. 5º, VIII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'seguranca-privada' and u.unit_key = 'art-64' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c36ccdb0d5920a17a81c5e6b4649acac76b0b84d0db01cfe1e921616003a27f8'
