insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os arts. 7º e 23 do Estatuto do Desarmamento passam a vigorar com nova redação: as armas utilizadas pelos profissionais de segurança privada serão de propriedade, responsabilidade e guarda das empresas, somente podendo ser utilizadas em serviço, com certificado de registro e autorização de porte expedidos pela Polícia Federal em nome da empresa; e as instituições de ensino policial, as guardas municipais e as escolas de formação de profissionais de segurança privada poderão adquirir insumos e máquinas de recarga de munição para suprimento exclusivo de suas atividades, mediante autorização.', '["Altera o art. 7º do Estatuto do Desarmamento.","Armas da empresa, uso apenas em serviço.","Altera o art. 23: escolas de formação podem adquirir máquinas de recarga."]'::jsonb, '["ATUALIZAÇÃO: altera o Estatuto do Desarmamento."]'::jsonb, 'A escola de formação pode adquirir insumos de recarga para treinar seus alunos.', '["Assertiva que permite o vigilante levar a arma para casa erra: uso só em serviço."]'::jsonb, '[]'::jsonb, '["Estatuto do Desarmamento"]'::jsonb, 'under_review', 'claude'
