insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 1º da Lei nº 10.446, de 8 de maio de 2002, passa a incluir, entre as infrações que a Polícia Federal pode investigar por repercussão interestadual ou internacional, o furto, roubo ou receptação de cargas, inclusive de produtos controlados como pólvoras e explosivos, transportadas em operação interestadual ou internacional, com indícios de quadrilha em mais de um Estado, e o furto, roubo ou dano contra empresas de segurança privada especializadas em transporte de valores.', '["Altera a Lei de atribuições da Polícia Federal.","Cargas de produtos controlados e transporte de valores."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 10.446, de 8 de maio de 2002."]'::jsonb, 'O roubo a carro-forte pode ser investigado pela Polícia Federal.', '["Assertiva que exclui o ataque a transportadoras de valores da atribuição da PF erra."]'::jsonb, '[]'::jsonb, '["Lei de atribuições da Polícia Federal"]'::jsonb, 'under_review', 'claude'
