insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Anexo traz a tabela de taxas dos serviços de fiscalização e controle da Polícia Federal, entre elas a vistoria de instalação de prestador (R$ 4.380,00), a vistoria de serviço orgânico (R$ 2.920,00), a autorização e a renovação de funcionamento de prestador (R$ 2.190,00), a autorização de serviço orgânico e sua renovação (R$ 730,00), a autorização para serviço adicional (R$ 730,00), a alteração de atos constitutivos (R$ 292,00), a vistoria de veículo especial (R$ 4.380,00), a mudança de uniforme (R$ 438,00), as autorizações de aquisição de armas e equipamentos e o cadastro de profissional (R$ 43,80).', '["Vistoria de prestador e de veículo especial: R$ 4.380,00.","Autorização e renovação de prestador: R$ 2.190,00.","Serviço orgânico: R$ 730,00.","Cadastro de profissional: R$ 43,80."]'::jsonb, '["Valores previstos na lei; confira eventuais atualizações da Polícia Federal."]'::jsonb, 'A empresa paga R$ 2.190,00 pela autorização de funcionamento.', '["Assertiva que fixa a taxa de autorização de prestador em R$ 730,00 erra: é R$ 2.190,00."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
